from collections import Counter
from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class LnbtsParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mnc, mcc = self.enb_ent_config['mnc'], self.enb_ent_config['mcc']

        self.set_parameter('enbName', 'TL' + self.enb_ent_config['id'].zfill(3))
        self.set_parameter('mnc', mnc)
        self.set_parameter('mcc', mcc)
        self.set_parameter('mncLength', self.getMncLength(mnc))
        self.set_actMultipleCarrier()
        self.set_parameter('supportedCellTechnology', self.getSupportedCellTechnology())

        if execution_config['is_fsm5']:
            self.set_parameter('actBbPooling', 'true')
            self.set_parameter('actEnhAcAndGbrServices', 'true')
            self.set_parameter('actMultBearers', 'true')
            self.set_parameter('congWeightAlg', 'qciPrio')
            self.set_parameter('bbPoolMinResource', 5)
            self.set_parameter('bbPoolEvalPeriod', 50)

        if execution_config['is_fsm6'] or execution_config['release'] >= 25.1:
            self.set_parameter('actQciArpToDscpMarking', 'true')

    def set_actMultipleCarrier(self):
        radio_ports = []
        for cell_ent in self.enb_ent_config['cells'].values():
            channels = cell_ent['channels']
            for channel in channels:
                if channel['direction'] == 'TX':
                    radio_ports.append(str(channel['radio'] + '-' + channel['port']))

        maxCarriersPerAnt = str(Counter(radio_ports).most_common(1)[0][1])
        if int(maxCarriersPerAnt) > 1:
            actMultipleCarrier = maxCarriersPerAnt + '_carrierOperation'
            self.set_parameter('actMultipleCarrier', actMultipleCarrier)

    def getSupportedCellTechnology(self):
        fdd_cells = self.enb_ent_config['cells_count_fdd']
        tdd_cells = self.enb_ent_config['cells_count_tdd']

        if fdd_cells > 0 and tdd_cells > 0:
            return 'mixed_FDD_TDD'
        elif fdd_cells > 0:
            return 'FDD'
        return 'TDD'

    @staticmethod
    def getMncLength(mnc):
        return str(len(mnc)) if len(mnc) == 3 else '2'
